export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const cells = Array.from({ length: d.length }, () => ({}));
  for (const r of d.ranges) for (let i = r[0]; i < r[1]; i++) cells[i] = clone(r[2]);
  for (const p of d.patches)
    for (let i = p.start; i < p.end; i++)
      for (const k of Object.keys(p.style)) {
        if (p.style[k] === null) delete cells[i][k];
        else cells[i][k] = p.style[k];
      }
  const key = (v) =>
    JSON.stringify(
      Object.keys(v)
        .sort()
        .map((k) => [k, v[k]]),
    );
  const out = [];
  for (let i = 0; i < cells.length; ) {
    let j = i + 1;
    while (j < cells.length && key(cells[j]) === key(cells[i])) j++;
    if (Object.keys(cells[i]).length) out.push([i, j, cells[i]]);
    i = j;
  }
  return out;
}

